package com.mahesh.empleave.notification;import com.mahesh.empleave.user.*;import lombok.*;import org.springframework.mail.*;import org.springframework.mail.javamail.*;import org.springframework.stereotype.*;@Service @RequiredArgsConstructor public class NotificationService{private final NotificationRepository repo;private final JavaMailSender mail;public void notify(AppUser u,String message){repo.save(new Notification(u,message));try{mail.send(SimpleMailMessageBuilder.build(u.getEmail(),message));}catch(Exception ignored){/* in-app notification remains durable when SMTP is not configured */}}static class SimpleMailMessageBuilder{static SimpleMailMessage build(String to,String text){var m=new SimpleMailMessage();m.setTo(to);m.setSubject("LeaveFlow notification");m.setText(text);return m;}}}
